import{_ as p,a0 as l,w as d,s,I as t,x as n,a1 as a,A as i,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"怎樣在廢舊的硬件上安裝 Xen 虛擬機監視器 | LCTT x X-CMD","titleTemplate":false,"description":"怎樣在廢舊的硬件上安裝 Xen 虛擬機監視器 | LCTT (201502) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎樣在廢舊的硬件上安裝 Xen 虛擬機監視器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎樣在廢舊的硬件上安裝 Xen 虛擬機監視器 | LCTT (201502) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201502/20141120 How to install Xen hypervisor on unused old hardware","title":"怎樣在廢舊的硬件上安裝 Xen 虛擬機監視器","tag":"201502","desc":""},"relativePath":"201502/20141120 How to install Xen hypervisor on unused old hardware.md","filePath":"[post].md"}'),u={name:"201502/20141120 How to install Xen hypervisor on unused old hardware.md"};function m(b,e,f,g,h,x){const r=l("Link");return d(),s("div",null,[e[29]||(e[29]=t("h1",{id:"怎樣在廢舊的硬件上安裝-xen-虛擬機監視器",tabindex:"-1"},[n("怎樣在廢舊的硬件上安裝 Xen 虛擬機監視器 "),t("a",{class:"header-anchor",href:"#怎樣在廢舊的硬件上安裝-xen-虛擬機監視器","aria-label":"Permalink to “怎樣在廢舊的硬件上安裝 Xen 虛擬機監視器”"},"​")],-1)),e[30]||(e[30]=t("p",null,"Xen 是一個直接運行在硬件上的虛擬機監視器，這意味着你必須準備一個裸機來安裝和運行 Xen。而 KVM 則和 Xen 有一些不同 —— 你可以把它添加到任何已經正在運行 Linux 的機器上。本教程描述瞭如何在廢舊的硬件上安裝和配置 Xen 虛擬機監視器。",-1)),t("p",null,[e[2]||(e[2]=n("整個安裝過程使用 Debian Jessie（Debian 的測試發行版）作為宿主機操作系統（也稱作 ",-1)),a(r,{href:"http://wiki.xen.org/wiki/Dom0"},{default:i(()=>[...e[0]||(e[0]=[n("Dom0",-1)])]),_:1}),e[3]||(e[3]=n("）。Jessie 並不是唯一的選擇 —— Xen 的支持是內建在 Linux 內核中的，",-1)),a(r,{href:"http://wiki.xen.org/wiki/Dom0_Kernels_for_Xen"},{default:i(()=>[...e[1]||(e[1]=[n("許多 Linux 發行版",-1)])]),_:1}),e[4]||(e[4]=n(" 都包含支持 Xen 的內核。",-1))]),e[31]||(e[31]=o('<h3 id="找點廢舊的硬件" tabindex="-1">找點廢舊的硬件 <a class="header-anchor" href="#找點廢舊的硬件" aria-label="Permalink to “找點廢舊的硬件”">​</a></h3><p>首先，找一個可以格式化的合適的工作站，比如一台舊的筆記本或者台式機。舊的硬件可能不適合玩遊戲，但是足夠安裝一個宿主機和一些客户機了。一個滿足下面這些要求的 PC 機就可以了。</p><ul><li>一個雙核 CPU（64 位）</li><li>4GB 內存</li><li>80GB 硬盤</li><li>能夠從 CD，DVD 或者 USB 引導啓動</li><li>一塊網卡</li></ul><p>注意 <strong>CPU 必須是 64 位的，因為 Debian 已經不再支持 32 位的 Xen 安裝包</strong>。如果你沒有空餘的硬件，你可以花點錢買一台舊機器。2010 年值 $1000 的旗艦級筆記本現在只需要 $100。從 eBay 買台二手筆記本並升級下內存也可以滿足需求。</p><h3 id="刻錄一個引導-cd-usb" tabindex="-1">刻錄一個引導 CD/USB <a class="header-anchor" href="#刻錄一個引導-cd-usb" aria-label="Permalink to “刻錄一個引導 CD/USB”">​</a></h3>',5)),t("p",null,[e[6]||(e[6]=n("下載 Debian Jessie 的 ISO 鏡像。從 ",-1)),a(r,{href:"https://www.debian.org/devel/debian-installer/"},{default:i(()=>[...e[5]||(e[5]=[n("Debian 官網",-1)])]),_:1}),e[7]||(e[7]=n(" 下載網絡安裝鏡像就可以了。",-1))]),e[32]||(e[32]=t("pre",null,[t("code",null,`$ wget http://cdimage.debian.org/cdimage/jessie_di_beta_2/amd64/iso-cd/debian-jessie-DI-b2-amd64-netinst.iso 
`)],-1)),t("p",null,[e[10]||(e[10]=n("接下來，記下你的 ",-1)),a(r,{href:"http://ask.xmodulo.com/detect-dvd-writer-device-name-writing-speed-command-line-linux.html"},{default:i(()=>[...e[8]||(e[8]=[n("CD/DVD",-1)])]),_:1}),e[11]||(e[11]=n(" 或者 ",-1)),a(r,{href:"http://ask.xmodulo.com/find-device-name-usb-drive-linux.html"},{default:i(()=>[...e[9]||(e[9]=[n("USB設備",-1)])]),_:1}),e[12]||(e[12]=n(" 所識別的設備名 （例如 /dev/sdc）。",-1))]),e[33]||(e[33]=o(`<p>使用 dd 命令將 ISO 鏡像刻錄至 CD 或者 USB 中。將下面的 /dev/sdc 替換為你上面識別出的設備名。</p><pre><code>$ sudo dd if=debian-jessie-DI-b2-amd64-netinst.iso of=/dev/sdc 
</code></pre><h3 id="開始安裝" tabindex="-1">開始安裝 <a class="header-anchor" href="#開始安裝" aria-label="Permalink to “開始安裝”">​</a></h3><p>安裝前，使用刻錄的 CD/USB 啓動 Debian 的安裝界面。</p><p>最好是使用有線網絡，而不是 WIFI。如果因為固件或者驅動的原因導致 WIFI 不能連接，你將無法完成下面的步驟。</p><p><img src="https://farm8.staticflickr.com/7516/15772286696_c31e4c7754_z.jpg" alt=""></p><h3 id="硬盤分區" tabindex="-1">硬盤分區 <a class="header-anchor" href="#硬盤分區" aria-label="Permalink to “硬盤分區”">​</a></h3><p>這裏的設置使用了四個分區。自動安裝時通常會創建一個包含邏輯分區的擴展分區。像下面這樣給硬盤分四個區。</p><ul><li>sda1 掛載至 /boot，200MB</li><li>sda2 做為 /, 20GB, Ubuntu 佔用 4GB</li><li>sda3 做為 swap, 6GB (4GB x 1.5 = 6)</li><li>sda4 保留用作 LVM, 不掛載，大小為剩餘的硬盤大小</li></ul><h3 id="安裝基本的系統" tabindex="-1">安裝基本的系統 <a class="header-anchor" href="#安裝基本的系統" aria-label="Permalink to “安裝基本的系統”">​</a></h3><p>這裏儘可能的讓系統的安裝更簡單快速一些。一個基本的工作用系統可以稍後再添加。Debian 的 APT（Advanced Package Tool）使得添加軟件非常的簡單。在機器上安裝 Debian 可能會有一些很浪費時間的問題。可能顯卡驅動與內核不監控或者可能老舊的 CD-ROM 驅動器只能間歇性的工作。</p><p>當選擇安裝軟件時，選擇安裝一個 SSH 服務器，不要安裝桌面環境如 Gnome。</p><p><img src="https://farm9.staticflickr.com/8541/15176520633_5d31beda9c_z.jpg" alt=""></p><p>安裝一個圖形桌面需要安裝成百上千的包 —— 這些額外的工作可以稍後再進行。如果你遇到問題了，等待圖形桌面的安裝會浪費很多時間。同時，沒有桌面組件，系統的啓動可以更快一些 —— 只需要幾十秒而不是幾分鐘。整個安裝過程會需要重啓幾次，因此這樣做可以節省不少時間。</p><p>一個 SSH 服務器可以讓你從另一台電腦來配置這台工作站。這可以避免一些舊硬件的問題 —— 可能舊機器的鍵盤少了幾個鍵，LCD 屏幕有壞點或者觸摸板沒有反應等等。</p><h3 id="添加-lvm-logical-volume-manager" tabindex="-1">添加 LVM (Logical Volume Manager) <a class="header-anchor" href="#添加-lvm-logical-volume-manager" aria-label="Permalink to “添加 LVM (Logical Volume Manager)”">​</a></h3><p>以 root 身份安裝 LVM 工具。</p><pre><code># apt-get update
# apt-get install lvm2
</code></pre><p>選擇一個分區創建物理卷。</p><pre><code># pvcreate /dev/sda4
</code></pre><p>創建卷組。</p><pre><code># vgcreate vg0 /dev/sda4
</code></pre><p>你並不需要創建邏輯卷。如果你想測試 LVM 是否正常，可以創建一個邏輯卷然後刪掉它。</p><pre><code># lvcreate -nmytempvol -L10G vg0
# lvremove /dev/vg0/mytempvol 
</code></pre><p>檢查 LVM 狀態。</p><pre><code># pvs (查看物理卷的信息)
# vgs (查看卷組的信息)
# lvs (查看邏輯卷的信息)
</code></pre><h3 id="添加一個-linux-網橋" tabindex="-1">添加一個 Linux 網橋 <a class="header-anchor" href="#添加一個-linux-網橋" aria-label="Permalink to “添加一個 Linux 網橋”">​</a></h3><p>這裏我們要添加一個橋接網卡，這樣 Xen 客户機就可以通過網橋連接網絡。</p><p>安裝橋接的工具。</p><pre><code># apt-get install bridge-utils
</code></pre><p>查看在哪塊網卡配置橋接。</p><pre><code># ip addr 
</code></pre><p><img src="https://farm8.staticflickr.com/7512/15610553338_2f9cf1d3a2_z.jpg" alt=""></p><p>在這個例子中，我們有一塊網卡名稱為 eth0。我們準備修改配置文件（/etc/network/interfaces）將 eth0 作為橋接設備。</p><p>在進行更改之前，備份網絡配置文件以保證原來的工作配置是安全的。</p><pre><code># cd /etc/network/
# cp interfaces interfaces.backup
# vi /etc/network/interfaces 
</code></pre><p>文件的內容類似下面這樣。</p><pre><code>auto lo
iface lo inet loopback
 
allow-hotplug eth0
iface eth0 inet dhcp
</code></pre><p>修改成這樣。</p><pre><code>auto lo
iface lo inet loopback
 
auto eth0
iface eth0 inet manual
 
auto xenbr0
iface xenbr0 inet dhcp
bridge_ports eth0
</code></pre><p>激活網卡配置的修改：</p><pre><code># systemctl restart networking 
</code></pre><h3 id="驗證網絡設置" tabindex="-1">驗證網絡設置 <a class="header-anchor" href="#驗證網絡設置" aria-label="Permalink to “驗證網絡設置”">​</a></h3><p>驗證橋接設備 xenbr0 創建成功。</p><pre><code># ip addr show xenbr0 
</code></pre><p>同時檢查 eth0 被成功加入網橋。</p><pre><code># brctl show 
</code></pre><p><img src="https://farm6.staticflickr.com/5609/15795960355_673c71ab5c_z.jpg" alt=""></p><p>你現在安裝好了 Jessie 系統。不過此時 Xen 還沒有安裝。下面我們開始安裝 Xen。</p><h3 id="安裝-xen-虛擬機監視器" tabindex="-1">安裝 Xen 虛擬機監視器 <a class="header-anchor" href="#安裝-xen-虛擬機監視器" aria-label="Permalink to “安裝 Xen 虛擬機監視器”">​</a></h3><p>安裝 Xen 和 QEMU 包，並升級 GRUB 引導程序。</p><pre><code># apt-get install xen-linux-system 
</code></pre><p>重啓。</p><p>當 GRUB 界面出現時，你可以看到列出的額外的啓動選項。</p><p><img src="https://farm8.staticflickr.com/7535/15794086091_bf1bce6b4b_z.jpg" alt=""></p><p>第一個選項會在 5 秒鐘內自動啓動（在 /etc/default/grub 的 GRUB_TIMEOUT 這行設置），因此這點時間可來不及喝咖啡。</p><p>按下方向鍵選擇 &quot;Debian GNU/Linux, with Xen hypervisor&quot; 這個選項，然後按回車。這時屏幕會出現很多行信息，接着是正常的登錄界面。</p><h3 id="檢查-xen-工作是否正常" tabindex="-1">檢查 Xen 工作是否正常 <a class="header-anchor" href="#檢查-xen-工作是否正常" aria-label="Permalink to “檢查 Xen 工作是否正常”">​</a></h3><p>Xen 虛擬機監視器帶有一個管理 Xen 的命令列程序叫做 xl，可以用來創建和管理 Xen 虛擬機。使用 xl 命令來檢查 Xen 是否成功安裝了。</p><p>以 root 用户登錄，執行:</p><pre><code># xl info
</code></pre><p>將會顯示很多關於 Xen 主機的信息。</p><p><img src="https://farm9.staticflickr.com/8404/15610553388_db3b134a9d_z.jpg" alt=""></p><p>查看已有 Xen 虛擬機的列表：</p><pre><code># xl list 
</code></pre><p><img src="https://farm9.staticflickr.com/8393/15610135189_ffd8bd24e8_z.jpg" alt=""></p><p>這裏顯示了一個主機的列表。因為沒有創建任何的 Xen 客户機，唯一的條目是 Domain-0，即你安裝的 Debian 系統。</p><h3 id="修改啓動順序" tabindex="-1">修改啓動順序 <a class="header-anchor" href="#修改啓動順序" aria-label="Permalink to “修改啓動順序”">​</a></h3><p>當你到這一步之後，Xen 的安裝已經完成了。這裏還有一件事需要修改 —— 默認的啓動選項不會加載 Xen。GRUB 選擇啓動菜單的第一個選項 （Debian GNU/Linux），而不是第三個（Debian GNU/Linux, with Xen hypervisor）。</p><p>啓動菜單的默認選項是在 grub 配置文件 /boot/grub/grub.cfg 中定義的。修改選項時，不要直接修改這個文件，而是編輯 /etc/default/grub 這個文件。有一個叫做 grub-mkconfig 的工具可以讀取這個配置文件和 /etc/grub.d/ 中的所有莫爸媽，並寫入到 grub.cfg 文件中。</p><p>編輯 Debian 的 grub-mkconfig 的配置文件</p><pre><code># vi /etc/default/grub 
</code></pre><p>修改這一行:</p><pre><code>GRUB_DEFAULT=0
</code></pre><p>改為</p><pre><code>GRUB_DEFAULT=&#39;Debian GNU/Linux, with Xen hypervisor&#39;
</code></pre><p>然後更新 grub 的配置文件。</p><pre><code># grub-mkconfig -o /boot/grub/grub.cfg 
</code></pre><p>最後重啓。幾秒鐘後，grub 啓動菜單出現了。檢查看第三個選項 &quot;Debian GNU/Linux, with Xen hypervisor&quot; 是否是自動選中的選項。</p><h3 id="最後" tabindex="-1">最後 <a class="header-anchor" href="#最後" aria-label="Permalink to “最後”">​</a></h3>`,80)),t("p",null,[e[14]||(e[14]=n("如果你使用這台主機作為你的工作站，可以安裝一個圖形桌面。Debian 包括好幾種",-1)),a(r,{href:"https://wiki.debian.org/DesktopEnvironment"},{default:i(()=>[...e[13]||(e[13]=[n("桌面環境",-1)])]),_:1}),e[15]||(e[15]=n("。如果你想要一個包含所有東西的圖形桌面，那麼安裝 Gnome 吧。如果它的圖形效果並不是你的菜，試試 Awesome 吧。",-1))]),e[34]||(e[34]=t("p",null,'注意 Debian 的默認 Gnome 環境有大量的額外應用程序包括辦公套件 LibreOffice，Iceweasel 瀏覽器和 Rhythmbox 音樂播放器。安裝命令 "apt-get install gnome" 會安裝 1,000 多個包並需要將近 2GB 的硬盤空間。運行這個重量級的桌面環境需要佔用 1GB 的內存。',-1)),e[35]||(e[35]=t("p",null,"（LCTT 譯註：本文沒有涉及如何安裝 guest 虛擬機，請關注後繼文章）",-1)),e[36]||(e[36]=t("hr",null,null,-1)),t("p",null,[e[17]||(e[17]=n("via: ",-1)),a(r,{href:"http://xmodulo.com/install-xen-hypervisor.html"},{default:i(()=>[...e[16]||(e[16]=[n("http://xmodulo.com/install-xen-hypervisor.html",-1)])]),_:1})]),t("p",null,[e[21]||(e[21]=n("作者：",-1)),a(r,{href:"http://xmodulo.com/author/nick"},{default:i(()=>[...e[18]||(e[18]=[n("Nick Hardiman",-1)])]),_:1}),e[22]||(e[22]=n(" 譯者：",-1)),a(r,{href:"https://github.com/liaoishere"},{default:i(()=>[...e[19]||(e[19]=[n("Liao",-1)])]),_:1}),e[23]||(e[23]=n(" 校對：",-1)),a(r,{href:"https://github.com/wxy"},{default:i(()=>[...e[20]||(e[20]=[n("wxy",-1)])]),_:1})]),t("p",null,[e[26]||(e[26]=n("本文由 ",-1)),a(r,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[24]||(e[24]=[n("LCTT",-1)])]),_:1}),e[27]||(e[27]=n(" 原創翻譯，",-1)),a(r,{href:"http://linux.cn/"},{default:i(()=>[...e[25]||(e[25]=[n("Linux中國",-1)])]),_:1}),e[28]||(e[28]=n(" 榮譽推出",-1))])])}const D=p(u,[["render",m]]);export{k as __pageData,D as default};
